// Generated by exit-ramp. A Deno KV-shaped facade over Workers KV (binding: KV).
//
// What matches Deno KV: get / getMany / set / delete / list({ prefix | start | end }) / tuple keys / structured values.
// What does NOT match, on purpose (read https://developers.cloudflare.com/kv/concepts/how-kv-works/):
//   - Consistency: Workers KV is eventually consistent. A write may take 60 seconds or more to be visible in other
//     locations, and "key not found" results are cached too. Deno KV reads are strongly consistent by default.
//   - No transactions: atomic() applies its operations one after another and can stop half way.
//     atomic().check() (optimistic concurrency with versionstamps) is refused unless you opt in to a racy emulation.
//   - Same-key writes are limited to 1 per second. Values are limited to 25 MiB, keys to 512 bytes after encoding.
//   - Entries have no versionstamp (always null). enqueue / listenQueue / watch / sum / min / max throw.
//   - list() reads values one key at a time (1 + N requests per page) and filters start/end/reverse in memory.
import { env } from "cloudflare:workers";
import { compareEncoded, decodeKey, deserialize, encodeKey, prefixFor, serialize, type KvKey, type KvKeyPart } from "./kv-codec";

export type { KvKey, KvKeyPart };

export interface KvEntry<T = unknown> {
  key: KvKey;
  value: T;
  versionstamp: string | null;
}
export interface KvEntryMaybe<T = unknown> {
  key: KvKey;
  value: T | null;
  versionstamp: string | null;
}
export interface KvCommitResult {
  ok: true;
  versionstamp: string;
}
export interface KvCommitError {
  ok: false;
}
export type KvListSelector = { prefix: KvKey; start?: KvKey; end?: KvKey } | { start: KvKey; end: KvKey; prefix?: undefined } | { start?: KvKey; end?: KvKey; prefix?: KvKey };
export interface KvListOptions {
  limit?: number;
  cursor?: string;
  reverse?: boolean;
  consistency?: "strong" | "eventual";
  batchSize?: number;
}
export interface KvCheck {
  key: KvKey;
  versionstamp: string | null;
}

export class ExitRampKvUnsupportedError extends Error {
  override name = "ExitRampKvUnsupportedError";
}

const MIN_TTL_SECONDS = 60; // Workers KV rejects expirationTtl below 60
const LIST_PAGE = 1000;
const GET_CONCURRENCY = 6;

export interface OpenKvOptions {
  /** Emulate atomic().check() with a read-then-write. This is NOT atomic: two writers can both pass the check. */
  unsafeBestEffortChecks?: boolean;
}

function stamp(): string {
  return String(Date.now()).padStart(20, "0");
}

export class Kv {
  constructor(private readonly ns: KVNamespace, readonly options: OpenKvOptions = {}) {}

  async get<T = unknown>(key: KvKey, _options?: { consistency?: "strong" | "eventual" }): Promise<KvEntryMaybe<T>> {
    const text = await this.ns.get(encodeKey(key), "text");
    return { key, value: text === null ? null : deserialize<T>(text), versionstamp: null };
  }

  async getMany<T extends readonly unknown[]>(keys: readonly [...{ [K in keyof T]: KvKey }]): Promise<{ [K in keyof T]: KvEntryMaybe<T[K]> }> {
    return (await Promise.all(keys.map((k) => this.get(k)))) as never;
  }

  async set(key: KvKey, value: unknown, options?: { expireIn?: number }): Promise<KvCommitResult> {
    const ttl = options?.expireIn === undefined ? undefined : Math.max(MIN_TTL_SECONDS, Math.ceil(options.expireIn / 1000));
    await this.ns.put(encodeKey(key), serialize(value), ttl === undefined ? undefined : { expirationTtl: ttl });
    return { ok: true, versionstamp: stamp() };
  }

  async delete(key: KvKey): Promise<void> {
    await this.ns.delete(encodeKey(key));
  }

  list<T = unknown>(selector: KvListSelector, options: KvListOptions = {}): KvListIterator<T> {
    return new KvListIterator<T>(this.ns, selector, options);
  }

  atomic(): AtomicOperation {
    return new AtomicOperation(this);
  }

  close(): void {}

  enqueue(): never {
    throw new ExitRampKvUnsupportedError("kv.enqueue is not available on Workers KV. Use Cloudflare Queues.");
  }
  listenQueue(): never {
    throw new ExitRampKvUnsupportedError("kv.listenQueue is not available on Workers KV. Use a Queues consumer.");
  }
  watch(): never {
    throw new ExitRampKvUnsupportedError("kv.watch is not available on Workers KV. Use Durable Objects (WebSocket hibernation) or polling.");
  }
}

export class KvListIterator<T> implements AsyncIterableIterator<KvEntry<T>> {
  private started = false;
  private buffer: KvEntry<T>[] = [];
  private pos = 0;
  private _cursor = "";
  constructor(private readonly ns: KVNamespace, private readonly selector: KvListSelector, private readonly options: KvListOptions) {}

  get cursor(): string {
    return this._cursor;
  }

  private async load(): Promise<void> {
    const { prefix, start, end } = this.selector;
    const p = prefix ? prefixFor(prefix) : "";
    let lower = start ? encodeKey(start) : p;
    const upper = end ? encodeKey(end) : undefined;
    if (this.options.cursor) lower = decodeCursor(this.options.cursor) + "\u0000";
    // Narrow the KV prefix query to the longest common prefix of the bounds.
    let scan = p;
    if (!prefix) {
      scan = "";
      if (start && end) {
        const a = encodeKey(start);
        const b = encodeKey(end);
        let i = 0;
        while (i < a.length && i < b.length && a[i] === b[i]) i++;
        scan = a.slice(0, i);
      }
    }
    const names: string[] = [];
    let cursor: string | undefined;
    for (;;) {
      const page = await this.ns.list({ prefix: scan || undefined, cursor, limit: LIST_PAGE });
      for (const k of page.keys) {
        if (compareEncoded(k.name, lower) < 0) continue;
        if (upper !== undefined && compareEncoded(k.name, upper) >= 0) continue;
        if (prefix && !k.name.startsWith(p)) continue;
        names.push(k.name);
      }
      if (page.list_complete) break;
      cursor = page.cursor;
      // Without reverse we can stop once we have enough names.
      if (!this.options.reverse && this.options.limit !== undefined && names.length >= this.options.limit) break;
    }
    if (this.options.reverse) names.reverse();
    const limited = this.options.limit === undefined ? names : names.slice(0, this.options.limit);
    const out: KvEntry<T>[] = [];
    for (let i = 0; i < limited.length; i += GET_CONCURRENCY) {
      const chunk = limited.slice(i, i + GET_CONCURRENCY);
      const texts = await Promise.all(chunk.map((n) => this.ns.get(n, "text")));
      chunk.forEach((n, j) => {
        const t = texts[j];
        if (t !== null) out.push({ key: decodeKey(n), value: deserialize<T>(t), versionstamp: null });
      });
    }
    this.buffer = out;
    if (out.length) this._cursor = encodeCursor(encodeKey(out[out.length - 1].key));
  }

  async next(): Promise<IteratorResult<KvEntry<T>>> {
    if (!this.started) {
      this.started = true;
      await this.load();
    }
    if (this.pos < this.buffer.length) return { value: this.buffer[this.pos++], done: false };
    return { value: undefined, done: true };
  }

  [Symbol.asyncIterator](): this {
    return this;
  }
}

function encodeCursor(s: string): string {
  return btoa(unescape(encodeURIComponent(s)));
}
function decodeCursor(s: string): string {
  return decodeURIComponent(escape(atob(s)));
}

type Mutation = { type: "set"; key: KvKey; value: unknown; expireIn?: number } | { type: "delete"; key: KvKey };

export class AtomicOperation {
  private checks: KvCheck[] = [];
  private mutations: Mutation[] = [];
  constructor(private readonly kv: Kv) {}

  check(...checks: KvCheck[]): this {
    this.checks.push(...checks);
    return this;
  }
  set(key: KvKey, value: unknown, options?: { expireIn?: number }): this {
    this.mutations.push({ type: "set", key, value, expireIn: options?.expireIn });
    return this;
  }
  delete(key: KvKey): this {
    this.mutations.push({ type: "delete", key });
    return this;
  }
  mutate(...ms: Mutation[]): this {
    for (const m of ms) {
      if (m.type !== "set" && m.type !== "delete") throw new ExitRampKvUnsupportedError(`atomic().mutate({ type: "${(m as { type: string }).type}" }) is not supported on Workers KV.`);
      this.mutations.push(m);
    }
    return this;
  }
  sum(): never {
    throw new ExitRampKvUnsupportedError("atomic().sum is not supported on Workers KV. Counters need Durable Objects (or D1).");
  }
  min(): never {
    throw new ExitRampKvUnsupportedError("atomic().min is not supported on Workers KV.");
  }
  max(): never {
    throw new ExitRampKvUnsupportedError("atomic().max is not supported on Workers KV.");
  }
  enqueue(): never {
    throw new ExitRampKvUnsupportedError("atomic().enqueue is not supported on Workers KV. Use Cloudflare Queues.");
  }

  async commit(): Promise<KvCommitResult | KvCommitError> {
    if (this.checks.length) {
      if (!this.kv.options.unsafeBestEffortChecks) {
        throw new ExitRampKvUnsupportedError(
          "atomic().check() needs versionstamps and compare-and-set, which Workers KV does not have. Move this key to a Durable Object or D1, or call openKv({ unsafeBestEffortChecks: true }) to accept a racy read-then-write.",
        );
      }
      for (const c of this.checks) {
        const current = await this.kv.get(c.key);
        const exists = current.value !== null;
        // versionstamp: null means "must not exist". Any other versionstamp cannot be verified; treat as "must exist".
        if (c.versionstamp === null ? exists : !exists) return { ok: false };
      }
    }
    for (const m of this.mutations) {
      if (m.type === "set") await this.kv.set(m.key, m.value, m.expireIn === undefined ? undefined : { expireIn: m.expireIn });
      else await this.kv.delete(m.key);
    }
    return { ok: true, versionstamp: stamp() };
  }
}

/** Replacement for `await Deno.openKv(path?)`. The path argument is ignored: the data lives in the KV binding. */
export async function openKv(options?: OpenKvOptions | string): Promise<Kv> {
  const binding = (env as unknown as { KV?: KVNamespace }).KV;
  if (!binding) throw new Error('No KV binding named "KV". Add a [[kv_namespaces]] entry to wrangler.toml.');
  return new Kv(binding, typeof options === "object" ? options : {});
}
